  /* -------------------------------------------- */

  /** @inheritDoc */
  static migrateData(source) {
    source = super.migrateData(source);

    if ( source.talents?.length ) {
      if ( typeof source.talents[0] === "string") {
        source.talents = source.talents.map(t => ({item: t, level: null}));
      }
    }

    return source;
  }
