    h.required = nHeroes * 4 * 3; // Generation rate: 4A per hero over 3 rounds
    h.previous = Math.floor(h.actions / h.required) * h.required;
    h.next = h.previous + h.required;
    h.pct = (h.actions - h.previous) / h.required;
